  <div id="st" style="position:absolute;top:870px;left:0;width:940px;text-align:center;color:#ffffff;font-size:52px;font-weight:900;opacity:0;letter-spacing:-1px;">14,777 GITHUB STARS</div>
`;

const cards = [0, 1, 2].map(i => root.querySelector('#c' + i));
const stars = root.querySelector('#st');
const lines = [0, 1].map(i => {
  const el = root.querySelector('#l' + i);
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});

function frame(t, p, d) {
  const mt = Math.min(t, d * 0.55);

  // Card 0
  const v0 = spr(mt, 0.1, 0.85, 12);
  cards[0].style.opacity = v0;
  cards[0].style.transform = `translateY(${lerp(40, 0, v0)}px) scale(${lerp(0.9, 1, v0)})`;

  // Line 0
  const vL0 = clamp((mt - 0.7) * 4);
  lines[0].el.style.strokeDashoffset = lines[0].len * (1 - vL0);

  // Card 1
  const v1 = spr(mt, 1.1, 0.85, 12);
  cards[1].style.opacity = v1;
  cards[1].style.transform = `translateY(${lerp(40, 0, v1)}px) scale(${lerp(0.9, 1, v1)})`;

  // Line 1
  const vL1 = clamp((mt - 1.7) * 4);
  lines[1].el.style.strokeDashoffset = lines[1].len * (1 - vL1);

  // Card 2
  const v2 = spr(mt, 2.1, 0.85, 12);
  cards[2].style.opacity = v2;
  cards[2].style.transform = `translateY(${lerp(40, 0, v2)}px) scale(${lerp(0.9, 1, v2)})`;

  // GitHub Stars
  const v3 = spr(mt, 2.7, 0.8, 10);
  stars.style.opacity = v3;
  stars.style.transform = `translateY(${lerp(20, 0, v3)}px)`;
}
